self.KB_CONTENT["card:753346"]={"id":"card:753346","ty":"card","sourceId":"753346","title":"『產能資料建立作業』中的『機台代號 (MZ001)』為何？","ver":"iGP","topic":"其他","keywords":[],"y":"other","answer":"* 可按[F2]機器代號資料查詢。* 預設：機器產能=機器產能。* 預設：有效機時=機器產能×負荷率。* 輸入後顯示機台名稱。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
