self.KB_CONTENT["card:783978"]={"id":"card:783978","ty":"card","sourceId":"783978","title":"『資產進貨單建立作業』中的『匯率 (TO009)』為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","資產","銀行","匯率"],"y":"other","answer":"* 當期匯率。* 此欄位必須大於零。* 依單據性質中的匯率來源設定，匯率查詢「I」=[F2]銀行買進匯率查詢。「O」=[F2]銀行賣出匯率查詢。「E」=[F2]報關買進匯率查詢。「W」=[F2]報關賣出匯率查詢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
