self.KB_CONTENT["card:755058"]={"id":"card:755058","ty":"card","sourceId":"755058","title":"『計價資料明細表』中的『選擇品號 (COP.MB002)』為何？","ver":"iGP","topic":"明細表","keywords":["明細表","品號","類別","計價"],"y":"other","answer":"* 提供區間選擇及離散點選兩種方式。* 若無勾選「區間選擇」，表示可離散點選資料。* 可點選(icon)或[F2]品號資料查詢，空白表篩選類別的全部品號資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
