self.KB_CONTENT["card:791803"]={"id":"card:791803","ty":"card","sourceId":"791803","title":"『請修派工維護作業』中的『廠務人員 (TB012)』為何？","ver":"GP4以上","topic":"其他","keywords":[],"y":"other","answer":"* 可按[F2]職務人員資料查詢，以輸入「職務代號」為F.廠務的人員資料。* 若「性質」為2.託外，則此欄位不可輸入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
