self.KB_CONTENT["field:793719"]={"id":"field:793719","ty":"field","sourceId":"793719","title":"貸方科目(零用金)","ver":"GP4以上","topic":"","keywords":[],"job":"分錄性質設定-借支申請","code":"MB014","answer":"* 可點選(icon)或[F2]會計科目資料查詢，並自動顯示科目名稱於後，但不允許空白。* 例：應付費用。","file":"fields.jsonl"};
