self.KB_CONTENT["field:815583"]={"id":"field:815583","ty":"field","sourceId":"815583","title":"修改目前格式","ver":"GP4.0 以上","topic":"","keywords":[],"job":"加工核價明細表","code":"","answer":"可請資訊人員到管理維護系統->基本資料管理->『使用者權限建立作業』查詢該使用者，點選修改，於單身找到MOCR18，給予【修改】的權限，後續即可於報表工作佇列點選【修改目前格式】。","file":"fields.jsonl"};
